def stratified_split(
    X: np.ndarray,
    y: np.ndarray,
    val_ratio: float = 0.2,
    seed: int = 42,
):
    """Stratified split using y-argmax as the label."""
    y_idx = np.argmax(y, axis=1)
    return train_test_split(X, y, test_size=val_ratio, random_state=seed, stratify=y_idx)

